const $ = (s) => document.querySelector(s);
const fmt = new Intl.NumberFormat('en-US');
const monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const boroughColors = ['#ff6b4a','#00a6a6','#4f7cac','#f4b942','#8e7dbe','#99a5b1'];
const state = {months:new Set(), boroughs:new Set(), scopes:new Set(), slots:new Set()};
let records, meta;

function selected(set, value){return !set.size || set.has(value)}
function matches(r, omit=''){return (omit==='month'||selected(state.months,r[0]))&&(omit==='borough'||selected(state.boroughs,r[1]))&&(omit==='scope'||selected(state.scopes,r[2]))&&(omit==='slot'||selected(state.slots,`${r[3]}-${r[4]}`))}
function countBy(length, index, omit){const a=Array(length).fill(0); for(const r of records) if(matches(r,omit)) a[r[index]]+=r[6]; return a}
function total(){let n=0;for(const r of records)if(matches(r))n+=r[6];return n}
function topIndex(values){return values.reduce((best,v,i)=>v>values[best]?i:best,0)}
function esc(s){return String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}
function toggle(key,value){state[key].has(value)?state[key].delete(value):state[key].add(value);render()}
function tip(text,event){const el=$('#tooltip');el.innerHTML=text;el.classList.add('visible');el.style.left=`${event.clientX+13}px`;el.style.top=`${event.clientY+13}px`}
function hideTip(){$('#tooltip').classList.remove('visible')}
function bindMarks(container){container.querySelectorAll('[data-key]').forEach(el=>{el.addEventListener('click',()=>toggle(el.dataset.key,Number.isNaN(+el.dataset.value)?el.dataset.value:+el.dataset.value));el.addEventListener('mousemove',e=>tip(el.dataset.tip,e));el.addEventListener('mouseleave',hideTip);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click()}})})}

function renderChips(){const labels=[];state.months.forEach(x=>labels.push(['months',x,monthNames[x-1]]));state.boroughs.forEach(x=>labels.push(['boroughs',x,meta.boroughs[x]]));state.scopes.forEach(x=>labels.push(['scopes',x,meta.scopes[x]]));state.slots.forEach(x=>{const [d,h]=x.split('-');labels.push(['slots',x,`${meta.weekdays[d]} · ${String(h).padStart(2,'0')}:00`])});$('#chips').innerHTML=labels.length?labels.map(([k,v,l])=>`<button class="chip" type="button" data-remove="${k}" data-value="${v}">${esc(l)} ×</button>`).join(''):'<span class="chip">All 2024 requests</span>';$('#chips').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state[b.dataset.remove].delete(isNaN(+b.dataset.value)?b.dataset.value:+b.dataset.value);render()});$('#clear').disabled=!labels.length}
function renderKPIs(){const all=total(), b=countBy(meta.boroughs.length,1), slots=countSlots();const status=countBy(meta.statuses.length,5);const closed=status.reduce((n,v,i)=>n+(meta.statuses[i]==='Closed'?v:0),0);$('#kpis').innerHTML=`<article class="kpi"><b>${fmt.format(all)}</b><span>reports in this view</span></article><article class="kpi"><b>${esc(meta.boroughs[topIndex(b)])}</b><span>loudest borough</span></article><article class="kpi"><b>${String(topIndex(slots)%24).padStart(2,'0')}:00</b><span>busiest hour</span></article><article class="kpi"><b>${all?Math.round(closed/all*100):0}%</b><span>marked closed</span></article>`}
function renderMonthly(){const counts=Array.from({length:12},()=>Array(meta.boroughs.length).fill(0));for(const r of records)if(matches(r,'month'))counts[r[0]-1][r[1]]+=r[6];const max=Math.max(...counts.map(x=>x.reduce((a,b)=>a+b,0)),1),w=1000,h=270,left=42,bottom=28,top=10,plotH=h-bottom-top;let s=`<svg viewBox="0 0 ${w} ${h}" role="img">`;for(let i=0;i<4;i++){const y=top+plotH-(i/3)*plotH;s+=`<line class="gridline" x1="${left}" y1="${y}" x2="${w-5}" y2="${y}"/><text class="axis-label" x="0" y="${y+4}">${fmt.format(Math.round(max*i/3))}</text>`}counts.forEach((row,m)=>{let used=0;row.forEach((n,b)=>{const bh=n/max*plotH,y=top+plotH-used-bh,x=left+m*78;const cls=state.months.has(m+1)||state.boroughs.has(b)?' is-selected':'';s+=`<rect class="bar-segment${cls}" tabindex="0" role="button" aria-label="${monthNames[m]}, ${meta.boroughs[b]}, ${fmt.format(n)} requests" data-key="months" data-value="${m+1}" data-tip="<b>${monthNames[m]} · ${meta.boroughs[b]}</b><br>${fmt.format(n)} requests" x="${x}" y="${y}" width="53" height="${bh}" fill="${boroughColors[b]}"/>`;used+=bh});s+=`<text class="axis-label" x="${left+m*78+26}" y="${h-7}" text-anchor="middle">${monthNames[m]}</text>`});s+='</svg>';$('#monthly').innerHTML=s;$('#borough-legend').innerHTML=meta.boroughs.map((b,i)=>`<button type="button" data-key="boroughs" data-value="${i}" data-tip="Filter: ${esc(b)}"><i style="background:${boroughColors[i]}"></i>${esc(b)}</button>`).join('');bindMarks($('#monthly'));bindMarks($('#borough-legend'))}
function renderBars(id, labels, values, key, colors){const max=Math.max(...values,1),w=520,h=Math.max(150,labels.length*33+22),left=118;let s=`<svg viewBox="0 0 ${w} ${h}" role="img">`;labels.forEach((l,i)=>{const y=12+i*33,bw=values[i]/max*(w-left-50),chosen=state[key].has(i)?' is-selected':'';s+=`<text class="bar-label" x="${left-9}" y="${y+16}" text-anchor="end">${esc(l)}</text><rect class="bar-row${chosen}" tabindex="0" role="button" aria-label="${esc(l)}, ${fmt.format(values[i])} requests" data-key="${key}" data-value="${i}" data-tip="<b>${esc(l)}</b><br>${fmt.format(values[i])} requests" x="${left}" y="${y}" width="${bw}" height="22" rx="3" fill="${colors[i]||'#2a9d8f'}"/><text class="bar-value" x="${left+bw+7}" y="${y+16}">${fmt.format(values[i])}</text>`});s+='</svg>';$(id).innerHTML=s;bindMarks($(id))}
function countSlots(){const a=Array(168).fill(0);for(const r of records)if(matches(r,'slot'))a[r[3]*24+r[4]]+=r[6];return a}
function renderHeatmap(){const slots=countSlots(),max=Math.max(...slots,1);let h='<div class="heat-grid"><span></span>';for(let x=0;x<24;x++)h+=`<span class="hour-label">${x}</span>`;for(let d=0;d<7;d++){h+=`<span class="heat-label">${meta.weekdays[d]}</span>`;for(let hour=0;hour<24;hour++){const i=d*24+hour,v=slots[i],light=96-(v/max*57),sel=state.slots.has(`${d}-${hour}`)?' is-selected':'';h+=`<button class="heatcell${sel}" type="button" aria-label="${meta.weekdays[d]} ${hour}:00, ${fmt.format(v)} requests" data-key="slots" data-value="${d}-${hour}" data-tip="<b>${meta.weekdays[d]} · ${String(hour).padStart(2,'0')}:00</b><br>${fmt.format(v)} requests" style="background:hsl(186,45%,${light}%)"></button>`}}h+='</div>';$('#heatmap').innerHTML=h;$('#heatmap').querySelectorAll('[data-key]').forEach(el=>{el.onclick=()=>toggle('slots',el.dataset.value);el.onmousemove=e=>tip(el.dataset.tip,e);el.onmouseleave=hideTip})}
function render(){renderChips();renderKPIs();renderMonthly();renderBars('#borough',meta.boroughs,countBy(meta.boroughs.length,1,'borough'),'boroughs',boroughColors);renderBars('#scope',meta.scopes,countBy(meta.scopes.length,2,'scope'),'scopes',['#e85d3f','#2a9d8f']);renderHeatmap()}
Promise.all([fetch('data/requests.json').then(r=>r.json()),fetch('data/meta.json').then(r=>r.json())]).then(([r,m])=>{records=r;meta=m;$('#source-count').textContent=`${fmt.format(meta.records)} requests loaded`;$('#method-text').textContent=`This dashboard loads all ${fmt.format(meta.records)} records in a fixed 2024 extract, then aggregates in the browser when you select a mark. ${meta.cleaning}`;$('#clear').onclick=()=>{Object.values(state).forEach(s=>s.clear());render()};render()}).catch(err=>{$('#source-count').textContent='Data could not load';$('#method-text').textContent=`The prepared request extract is unavailable: ${err.message}`;console.error(err)});

